import java.util.Scanner;

public class Main {
    static final int N = 1000010;
    static int n, k, P;
    static long[] fac = new long[N], ifac = new long[N];
    static int[] f = new int[N], g = new int[N];

    static long qpow(long a, long n) {
        long r = 1 % P;
        a %= P;
        while (n > 0) {
            if ((n & 1) == 1) r = r * a % P;
            a = a * a % P;
            n >>= 1;
        }
        return r;
    }

    static long inv(long x) {
        if (x <= 1) return 1;
        return inv(P % x) * (P - P / x) % P;
    }

    static void add(int[] a, int index, long b) {
        a[index] = (int)((a[index] + b) % P);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        P = sc.nextInt();

        fac[0] = 1;
        for (int i = 1; i < N; i++) {
            fac[i] = fac[i - 1] * i % P;
        }

        ifac[N - 1] = inv(fac[N - 1]);
        for (int i = N - 2; i >= 0; i--) {
            ifac[i] = ifac[i + 1] * (i + 1) % P;
        }

        long ans = qpow(k, n);
        if (n % 2 == 0) {
            f[n] = (int)fac[n];
            for (int z = 1; z <= k; z++) {
                for (int i = 0; i <= n; i++) {
                    g[i] = 0;
                }
                for (int i = n; i > 0; i = (i - 1) & n) {
                    if (f[i] != 0) {
                        for (int j = i; 2 * j >= i; j = (j - 1) & i) {
                            add(g, i ^ j, f[i] * ifac[j]);
                        }
                    }
                }
                for (int i = 0; i <= n; i++) {
                    f[i] = g[i];
                }
                int res = f[0];
                for (int j = 0; j < z; j++) {
                    res = (int)((long)res * (k - j) % P);
                }
                ans = (ans - res) % P;
            }
        }
        if (ans < 0) ans += P;
        System.out.println(ans);
        sc.close();
    }
}

